//----------------------------------------------------------------------------------------------------------------------------------
// build_id.c - the build identity as data: one record with the version string, the commit hash and the commit time
// (build_time.h, generated by the Makefile from git or from PC_FW_BUILD / SOURCE_DATE_EPOCH). Code reads it instead of
// compiling the values in, so a different commit changes these bytes and nothing else: the code size and the layout of
// the image do not depend on the identity.
//
// Linked last (Makefile SRCS) and the only object here, so the record is the last thing in the image (.rodata is the
// last loaded section, fnirsi_1013d.ld) and a reader finds it at the image's tail, before mksunxi's zero padding
// (fw 0.2.52, pc_ident.h, protocol row 55). fw 0.2.47-0.2.51 had two objects here (u32 pc_fw_build, u8 pc_build_time[6]);
// pc_ident.c still reads their tail.
//----------------------------------------------------------------------------------------------------------------------------------

#include <stdint.h>
#include "build_time.h"
#include "pc_protocol.h"
#include "pc_ident.h"
#include "pc_cmds.h"

//fw 0.2.100: a three-digit patch makes the version longer. pc_image_id.version holds 15 characters and its NUL (the
//readers stop at 15: ui_diag.c s_ver, the card scan); C accepts a 16-character initializer without the NUL, so check
//it here ("0.2.100-m1-nommu", both A/B suffixes at once, is 16 and does not build)
typedef char pc_fw_version_fits[(sizeof(PC_FW_VERSION) <= sizeof(((pc_image_id *)0)->version)) ? 1 : -1];

const pc_image_id pc_image_ident =
{
  PC_ID_MAGIC0, PC_ID_MAGIC1,
  PC_FW_VERSION,
  PC_FW_BUILD,
  { COMPILE_YEAR, COMPILE_MONTH, COMPILE_DAY, COMPILE_HOUR, COMPILE_MIN, COMPILE_SEC },
  PC_PROTO_MAJOR, PC_PROTO_MINOR
};
